#include "os.h"
#include "sys.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

#define TASK_MAIN_NAME  "main"
#define TASK_MAIN_PRI   1    

#ifndef TASK_MAIN_STK
  #define TASK_MAIN_STK   0x0280
#endif

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

void task_main    (void * tsk_arg) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

int main (void)
{
  os_sys_init_func = sys_init ;
  os_sys_idle_func = sys_idle ;

  os_execute (task_main , TASK_MAIN_PRI , TASK_MAIN_STK , 0 , TASK_MAIN_NAME , (void *) 0xdeadbeef , OS_STK_SIZE) ;
}

